          if (authConfigs.getServerIdentityValue().equals(serverIdentity)) {
              chain.doFilter(request, response);
              return;
          }
          Loggers.AUTH.warn("Invalid server identity value for {} from {}", authConfigs.getServerIdentityKey(),
                  req.getRemoteHost());
      } else {
